-- Explicit reference cards, not ownership transfer or media copies.
-- Generated by Supabase CLI; normalized to the repository's forward prefix.
BEGIN;
CREATE TABLE public.post_destination_references (
 id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
 owner_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE,
 post_id uuid REFERENCES public.posts(id) ON DELETE SET NULL,
 memory_item_id uuid UNIQUE REFERENCES public.memory_items(id) ON DELETE CASCADE,
 highlight_id uuid UNIQUE REFERENCES public.highlights(id) ON DELETE CASCADE,
 operation_id uuid NOT NULL,
 intent_hash text NOT NULL,
 created_at timestamptz NOT NULL DEFAULT now(),
 CONSTRAINT post_reference_one_destination CHECK (num_nonnulls(memory_item_id,highlight_id)=1),
 UNIQUE(owner_id,operation_id)
);
CREATE INDEX post_destination_references_post_idx ON public.post_destination_references(post_id) WHERE post_id IS NOT NULL;
ALTER TABLE public.post_destination_references ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.post_destination_references FROM PUBLIC,anon,authenticated;
GRANT SELECT,INSERT,UPDATE,DELETE ON public.post_destination_references TO service_role;
COMMENT ON TABLE public.post_destination_references IS 'Service-only provenance for explicitly rendered post-reference cards. Contains no source text or media URL. Every card read must authorize the destination and re-resolve the source for that viewer.';
-- A deleted destination must not be resurrected by a delayed network retry.
CREATE TABLE public.post_destination_operations (
 owner_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE,
 operation_id uuid NOT NULL, intent_hash text NOT NULL, result_json jsonb NOT NULL,
 created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(owner_id,operation_id)
);
ALTER TABLE public.post_destination_operations ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.post_destination_operations FROM PUBLIC,anon,authenticated;
GRANT SELECT,INSERT ON public.post_destination_operations TO service_role;

-- Any writer that tries to masquerade an ordinary image/URL as a reference
-- must have a matching provenance row in the same transaction. The deferred
-- check lets the canonical command write and its reference commit atomically.
CREATE OR REPLACE FUNCTION public.post_reference_destination_guard()
RETURNS trigger LANGUAGE plpgsql SECURITY INVOKER SET search_path=pg_catalog,public AS $$
DECLARE actual_url text; actual_type text; linked boolean;
BEGIN
 IF TG_TABLE_NAME='memory_items' THEN
  SELECT media_url,media_type INTO actual_url,actual_type FROM public.memory_items WHERE id=NEW.id;
  IF NOT FOUND OR actual_type<>'application/vnd.portava.post-reference+json' THEN RETURN NULL; END IF;
  SELECT EXISTS(SELECT 1 FROM public.post_destination_references r JOIN public.memory_items i ON i.id=r.memory_item_id JOIN public.memories m ON m.id=i.memory_id
   WHERE i.id=NEW.id AND r.owner_id=m.owner_id AND actual_url='portava-post-reference:'||r.id::text) INTO linked;
 ELSE
  SELECT media_url,media_type INTO actual_url,actual_type FROM public.highlights WHERE id=NEW.id;
  IF NOT FOUND OR actual_type<>'application/vnd.portava.post-reference+json' THEN RETURN NULL; END IF;
  SELECT EXISTS(SELECT 1 FROM public.post_destination_references r JOIN public.highlights h ON h.id=r.highlight_id
   WHERE h.id=NEW.id AND r.owner_id=h.owner_id AND actual_url='portava-post-reference:'||r.id::text) INTO linked;
 END IF;
 IF NOT linked THEN RAISE EXCEPTION 'post_reference_provenance_required'; END IF;
 RETURN NULL;
END $$;
REVOKE ALL ON FUNCTION public.post_reference_destination_guard() FROM PUBLIC,anon,authenticated;
CREATE CONSTRAINT TRIGGER memory_post_reference_guard AFTER INSERT OR UPDATE ON public.memory_items
 DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION public.post_reference_destination_guard();
CREATE CONSTRAINT TRIGGER highlight_post_reference_guard AFTER INSERT OR UPDATE ON public.highlights
 DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION public.post_reference_destination_guard();

CREATE OR REPLACE FUNCTION public.share_post_to_destination(
 p_actor_id uuid,p_post_id uuid,p_operation_id uuid,p_destination text,
 p_memory_id uuid DEFAULT NULL,p_title text DEFAULT NULL,p_note text DEFAULT NULL,p_visibility text DEFAULT NULL)
RETURNS jsonb LANGUAGE plpgsql SECURITY INVOKER SET search_path=pg_catalog,public AS $$
<<destination>>
DECLARE post public.posts; existing public.post_destination_references; reference_id uuid:=gen_random_uuid();
 memory_id uuid:=p_memory_id; item_id uuid; highlight_id uuid; pos integer; fingerprint text; result jsonb; command jsonb;
 effective_visibility text; uri text; row_memory public.memories; memory_created boolean:=false;
 prior public.post_destination_operations;
BEGIN
 IF p_actor_id IS NULL OR p_post_id IS NULL OR p_operation_id IS NULL OR p_destination NOT IN ('memory','highlight') OR p_destination IS NULL
  OR char_length(coalesce(p_title,''))>120 OR char_length(coalesce(p_note,''))>500 THEN RAISE EXCEPTION 'invalid_destination'; END IF;
 effective_visibility=coalesce(p_visibility,CASE WHEN p_destination='memory' THEN 'only_me' ELSE 'public' END);
 IF (p_destination='memory' AND effective_visibility NOT IN ('only_me','public','friends_only'))
  OR (p_destination='highlight' AND effective_visibility NOT IN ('private','public'))
  OR (p_destination='highlight' AND p_memory_id IS NOT NULL) THEN RAISE EXCEPTION 'invalid_destination'; END IF;
 fingerprint=encode(sha256(convert_to(jsonb_build_object('post',p_post_id,'destination',p_destination,'memory',p_memory_id,'title',p_title,'note',p_note,'visibility',effective_visibility)::text,'UTF8')),'hex');
 -- Serialize this owner's retries, including CREATE_MEMORY where no target
 -- row exists yet. The lock key contains no secret and never leaves the DB.
 PERFORM pg_advisory_xact_lock(hashtextextended('post-destination:'||p_actor_id::text||':'||p_operation_id::text,0));
 SELECT * INTO prior FROM public.post_destination_operations WHERE owner_id=p_actor_id AND operation_id=p_operation_id;
 IF FOUND THEN
  IF prior.intent_hash<>fingerprint THEN RAISE EXCEPTION 'destination_intent_conflict'; END IF;
  IF NOT EXISTS(SELECT 1 FROM public.post_destination_references r
    LEFT JOIN public.memory_items i ON i.id=r.memory_item_id LEFT JOIN public.memories m ON m.id=i.memory_id
    LEFT JOIN public.highlights h ON h.id=r.highlight_id
    WHERE r.id=(prior.result_json->>'referenceId')::uuid AND r.owner_id=p_actor_id
      AND ((m.id IS NOT NULL AND m.state NOT IN ('deleted','removed')) OR (h.id IS NOT NULL AND h.deleted_at IS NULL)))
   THEN RAISE EXCEPTION 'destination_unavailable'; END IF;
  RETURN prior.result_json||jsonb_build_object('replayed',true);
 END IF;
 SELECT * INTO post FROM public.posts WHERE id=p_post_id FOR SHARE;
 IF NOT FOUND OR post.author_id IS NULL OR post.deleted_at IS NOT NULL OR post.status::text IS DISTINCT FROM 'active'
  OR (post.author_id<>p_actor_id AND (post.visibility::text IS DISTINCT FROM 'public' OR post.post_status::text IS DISTINCT FROM 'published'
    OR post.reposting_disabled OR post.sharing_disabled))
  OR EXISTS(SELECT 1 FROM public.blocks WHERE (blocker_id=p_actor_id AND blocked_id=post.author_id) OR (blocked_id=p_actor_id AND blocker_id=post.author_id))
  OR NOT EXISTS(SELECT 1 FROM public.profiles WHERE id=post.author_id AND coalesce(account_status::text,'active')='active')
  OR (post.author_id<>p_actor_id AND EXISTS(SELECT 1 FROM public.profiles WHERE id=post.author_id AND is_private=true)
    AND NOT EXISTS(SELECT 1 FROM public.user_follows WHERE follower_id=p_actor_id AND following_id=post.author_id))
  OR EXISTS(SELECT 1 FROM public.user_account_states WHERE user_id IN (post.author_id,p_actor_id)
    AND state IN ('banned','suspended') AND (expires_at IS NULL OR expires_at>now()))
 THEN RAISE EXCEPTION 'source_post_unavailable'; END IF;
 uri='portava-post-reference:'||reference_id::text;
 command=jsonb_build_object('command_id',gen_random_uuid(),'actor_user_id',p_actor_id,'correlation_id',p_operation_id,
  'idempotency_key','post-destination:'||p_operation_id::text,'client_observed_at',NULL,'schema_version',1);
 IF p_destination='memory' THEN
  IF memory_id IS NULL THEN
   result=public.memory_kernel_execute(command||jsonb_build_object('type','CREATE_MEMORY','idempotency_key','post-destination:'||p_operation_id::text||':memory',
    'payload',jsonb_build_object('write',jsonb_build_object('title',nullif(btrim(p_title),''),'visibility',effective_visibility,'state','published','owner_id',p_actor_id))));
   IF result->>'ok' IS DISTINCT FROM 'true' THEN RAISE EXCEPTION 'destination_command_refused'; END IF;
   memory_id=(result#>>'{result,id}')::uuid; memory_created=true;
  END IF;
  SELECT * INTO row_memory FROM public.memories WHERE id=memory_id FOR UPDATE;
  IF NOT FOUND OR row_memory.owner_id<>p_actor_id OR row_memory.state IN ('deleted','removed','archived') THEN RAISE EXCEPTION 'destination_unavailable'; END IF;
  -- A repeated save to the same Memory returns its existing reference.
  SELECT r.* INTO existing FROM public.post_destination_references r JOIN public.memory_items i ON i.id=r.memory_item_id
   WHERE r.owner_id=p_actor_id AND r.post_id=p_post_id AND i.memory_id=destination.memory_id ORDER BY r.created_at LIMIT 1;
  IF FOUND THEN
   result=jsonb_build_object('referenceId',existing.id,'memoryId',memory_id,'highlightId',NULL,'replayed',true);
   INSERT INTO public.post_destination_operations VALUES(p_actor_id,p_operation_id,fingerprint,result,now());
   RETURN result;
  END IF;
  IF (SELECT count(*) FROM public.memory_items WHERE memory_items.memory_id=destination.memory_id)>=10 THEN RAISE EXCEPTION 'destination_full'; END IF;
  SELECT coalesce(max(position),-1)+1 INTO pos FROM public.memory_items WHERE memory_items.memory_id=destination.memory_id;
  result=public.memory_kernel_execute(command||jsonb_build_object('command_id',gen_random_uuid(),'type','ADD_MEDIA','memory_id',memory_id,
   'payload',jsonb_build_object('media_type','application/vnd.portava.post-reference+json','position',pos,
    'write',jsonb_build_object('memory_id',memory_id,'media_url',uri,'media_type','application/vnd.portava.post-reference+json','caption',nullif(btrim(p_note),''),'position',pos))));
  IF result->>'ok' IS DISTINCT FROM 'true' THEN RAISE EXCEPTION 'destination_command_refused'; END IF;
  item_id=(result#>>'{result,id}')::uuid;
 ELSE
  result=public.highlight_create_execute(command||jsonb_build_object('type','CREATE_HIGHLIGHT','payload',jsonb_build_object(
   'media_url',uri,'media_type','application/vnd.portava.post-reference+json','caption',nullif(btrim(p_note),''),
   'visibility',effective_visibility,'expires_in_hours',24,'lifetime_class','DAY','filter_id','original','filter_intensity',100)));
  IF result->>'ok' IS DISTINCT FROM 'true' THEN RAISE EXCEPTION 'destination_command_refused'; END IF;
  highlight_id=(result#>>'{result,id}')::uuid;
 END IF;
 INSERT INTO public.post_destination_references(id,owner_id,post_id,memory_item_id,highlight_id,operation_id,intent_hash)
  VALUES(reference_id,p_actor_id,p_post_id,item_id,highlight_id,p_operation_id,fingerprint);
 result=jsonb_build_object('referenceId',reference_id,'memoryId',memory_id,'highlightId',highlight_id,'memoryCreated',memory_created,'replayed',false);
 INSERT INTO public.post_destination_operations VALUES(p_actor_id,p_operation_id,fingerprint,result,now());
 RETURN result;
END $$;
REVOKE ALL ON FUNCTION public.share_post_to_destination(uuid,uuid,uuid,text,uuid,text,text,text) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.share_post_to_destination(uuid,uuid,uuid,text,uuid,text,text,text) TO service_role;
COMMIT;
